import{validTrials}from'./path-trials.js';
import{COSMETICS,validCosmetics}from'./cosmetics.js';
import{validEncounters}from'./path-combat.js';
import{CHAPTER_LENGTH,START,activeNode,approachPoint}from'./trail-layout.js';
export const TRAILS=[{id:'air',name:'Silver wind',cost:0,color:'#d6f4df'},{id:'mint',name:'Emerald leaves',cost:35,color:'#70edb5'},{id:'amber',name:'Golden sparks',cost:55,color:'#f4cc73'},{id:'violet',name:'Violet stars',cost:75,color:'#c1a1f0'}];
export function freshWallet(){return{balance:0,total:0,owned:['air'],equipped:'air'};}
export function travelState(e){return e.travel??={collected:[],completed:[],earned:0,retries:0,safe:{...START,y:0,heading:Math.PI}};}
export function collectCoin(save,e,coin){const travel=travelState(e);if(travel.collected.includes(coin.id))return 0;save.wallet??=freshWallet();const value=save.mode==='challenge'?2:1;travel.collected.push(coin.id);travel.earned+=value;save.wallet.balance+=value;save.wallet.total+=value;return value;}
export function equipTrail(save,id){const trail=TRAILS.find(t=>t.id===id);if(!trail)return false;const wallet=save.wallet??=freshWallet();if(!wallet.owned.includes(id)){if(wallet.balance<trail.cost)return false;wallet.balance-=trail.cost;wallet.owned.push(id);}wallet.equipped=id;return true;}
const oldStops=[9,2,-6,-14,-27,-40,-53,-62],newStops=[9,2,-9,-28,-58,-88,-118,-130];
export function remapOldPosition(p){if(!p)return p;const chapter=Math.max(0,Math.min(4,Math.floor((2-p.z)/64))),local=p.z+chapter*64;let mapped=local;for(let i=1;i<oldStops.length;i++)if(local<=oldStops[i-1]&&local>=oldStops[i]){const t=(oldStops[i-1]-local)/(oldStops[i-1]-oldStops[i]);mapped=newStops[i-1]+(newStops[i]-newStops[i-1])*t;break;}if(local< -62)mapped=-130+(local+62);return{...p,z:mapped-chapter*CHAPTER_LENGTH};}
// Coordinates expand once; identity, language state and branch choices stay intact.
export function upgradeTraversalSave(save){save.wallet??=freshWallet();for(const j of Object.values(save.journeys||{}))for(const e of Object.values(j.expeditions||{})){if(e.layoutVersion!==2){e.position=remapOldPosition(e.position);if(e.checkpoint?.position)e.checkpoint.position=remapOldPosition(e.checkpoint.position);for(const cp of e.checkpointHistory||[])if(cp.position)cp.position=remapOldPosition(cp.position);e.layoutVersion=2;if(e.active){const node=activeNode(e);if(node)e.position=approachPoint(node);}const travel=travelState(e);travel.completed=Array.from({length:Math.min(20,e.index+(e.active?1:0))},(_,i)=>i);travel.safe={...e.position,y:0,heading:e.heading};}travelState(e);if(e.adventureVersion===undefined){e.adventureVersion=1;e.legacyThrough=e.index;}}return save;}
export function validTravel(e){if(e.layoutVersion!==undefined&&e.layoutVersion!==2)return false;if(e.travel==null)return true;if(typeof e.travel!=='object'||Array.isArray(e.travel))return false;const t=e.travel;return validTrials(e)&&validEncounters(e)&&Array.isArray(t.collected)&&t.collected.length<=500&&t.collected.every(id=>typeof id==='string'&&id.startsWith(e.id+':travel:'))&&new Set(t.collected).size===t.collected.length&&Array.isArray(t.completed)&&t.completed.every(i=>Number.isInteger(i)&&i>=0&&i<20)&&new Set(t.completed).size===t.completed.length&&Number.isInteger(t.earned)&&t.earned>=0&&Number.isInteger(t.retries)&&t.retries>=0&&t.safe&&Number.isFinite(t.safe.x)&&Number.isFinite(t.safe.z)&&Math.abs(t.safe.x)<35&&t.safe.z<12&&t.safe.z> -700;}
export function validWallet(wallet){return wallet==null||typeof wallet==='object'&&!Array.isArray(wallet)&&Number.isInteger(wallet.balance)&&wallet.balance>=0&&wallet.balance<=1e9&&Number.isInteger(wallet.total)&&wallet.total>=wallet.balance&&wallet.total<=1e9&&Array.isArray(wallet.owned)&&wallet.owned.includes('air')&&wallet.owned.every(id=>TRAILS.some(t=>t.id===id)||COSMETICS.some(c=>c.id===id))&&TRAILS.some(t=>t.id===wallet.equipped)&&wallet.owned.includes(wallet.equipped)&&validCosmetics(wallet);}
